"use client"

import * as React from "react"

// The chart's shared state: its config, its id (which scopes the hatch patterns) and the defaults that give every
// series an ink and a hatch, so series differ by pattern as well as colour.

// Format: { THEME_NAME: CSS_SELECTOR }. Patina's night paper is data-theme="night" on the root, not shadcn's .dark.
export const THEMES = { light: "", dark: ':root[data-theme="night"]' } as const

/** The hatch a series fills its bars, areas and slices with. */
export type ChartHatch =
  "diagonal" | "cross" | "dots" | "horizontal" | "antidiagonal"

/** Series without a hatch take the next one in this order. */
export const CHART_HATCHES: readonly ChartHatch[] = [
  "diagonal",
  "cross",
  "dots",
  "horizontal",
  "antidiagonal",
]

/** Series without a colour take the next drum in this order, so a chart re-inks with the page's ink set. Red comes
 * before blue because blue beside the violet detail drum is too close to tell apart (dataviz validator). */
export const CHART_INKS: readonly string[] = [
  "var(--print-line)",
  "var(--print-accent)",
  "var(--print-detail)",
  "var(--print-red)",
  "var(--print-blue)",
]

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode
    icon?: React.ComponentType
    /** Patina: the series' hatch; defaults by position in the config. */
    hatch?: ChartHatch
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>

type ChartContextProps = {
  config: ChartConfig
  /** Scopes the chart's hatch patterns, so several charts on a page never share an id. */
  chartId: string
}

export const ChartContext = React.createContext<ChartContextProps | null>(null)

export function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

/** The id of a series' hatch pattern inside one chart. */
export function hatchId(chartId: string, key: string) {
  return `${chartId}-hatch-${key.replace(/[^\w-]/g, "_")}`
}

/** A series' ink and hatch, explicit or by its position in the config. */
export function seriesStyle(config: ChartConfig, key: string) {
  const index = Math.max(0, Object.keys(config).indexOf(key))
  const item = config[key]
  return {
    color: item?.color ?? CHART_INKS[index % CHART_INKS.length]!,
    hatch: item?.hatch ?? CHART_HATCHES[index % CHART_HATCHES.length]!,
  }
}

/** Whether a fill refers to a series' hatch (var(--hatch-<key>) or its pattern id), not an ink or a gradient. */
export function isHatchFill(value: unknown): value is string {
  return typeof value === "string" && value.includes("-hatch-")
}

/**
 * The config key an item belongs to: the value of `key` on the item or its data row (a pie slice's name, say),
 * else `key` itself. Undefined when neither is in the config.
 */
export function getPayloadConfigKey(
  config: ChartConfig,
  payload: unknown,
  key: string,
): string | undefined {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  if (configLabelKey in config) return configLabelKey
  return key in config ? key : undefined
}

"use client"

import * as React from "react"
import rough from "roughjs"
import {
  Sector,
  type BarShapeProps,
  type CurveProps,
  type PieSectorShapeProps,
} from "recharts"
import { seedOf } from "@/patina/ink/seed"

// Drawn data marks. rough.js redraws each stroke as two loose pen passes with preserveVertices, so every vertex (a
// data point, a bar's corner) stays exactly where Recharts put it and only the stretch between two vertices wobbles,
// by under a pixel at this roughness. Fills stay exact geometry. Seeds come from the series and its data, never
// from layout, and inputs are snapped to hundredths as in ink/rough, so server and browser draw the same strokes.

type Point = [number, number]
type Op = { op: "move" | "lineTo" | "bcurveTo"; data: number[] }

const gen = rough.generator()
const PEN = {
  roughness: 0.5,
  bowing: 0.6,
  maxRandomnessOffset: 2,
  preserveVertices: true,
  stroke: "currentColor",
  strokeWidth: 1.5,
}
const q = (n: number) => Math.round(n * 100) / 100
const tenth = (n: number) => Math.round(n * 10) / 10

// Recharts re-renders shapes on hover and while animating; a small cache keeps a redraw of the same geometry free.
const cache = new Map<string, Op[]>()
function roughOps(d: string, seed: number): Op[] {
  const key = `${seed}|${d}`
  let ops = cache.get(key)
  if (!ops) {
    const drawable = gen.path(d, { ...PEN, seed: seed || 1 })
    ops = drawable.sets.flatMap((set) => set.ops as Op[])
    cache.set(key, ops)
    if (cache.size > 400) cache.delete(cache.keys().next().value as string)
  }
  return ops
}

function opsToPath(ops: Op[]) {
  return ops
    .map(({ op, data }) => {
      const n = data.map(tenth).join(" ")
      return op === "move" ? `M${n}` : op === "lineTo" ? `L${n}` : `C${n}`
    })
    .join("")
}

/** The ink a drawn outline takes: an explicit stroke, else the colour of the series whose hatch fills it. */
function inkOf(fill: unknown, stroke: unknown, key: unknown) {
  if (typeof stroke === "string" && stroke !== "none" && stroke !== "#fff")
    return stroke
  const hatch = typeof fill === "string" && fill.match(/--hatch-([\w-]+)/)
  if (hatch) return `var(--color-${hatch[1]})`
  if (typeof key === "string") return `var(--color-${key}, var(--ink))`
  return typeof fill === "string" ? fill : "var(--ink)"
}

// ---- Curves -------------------------------------------------------------------------------------------------------

type CurveFactory = Extract<
  NonNullable<CurveProps["type"]>,
  (...args: never[]) => unknown
>
type CurveContext = Parameters<CurveFactory>[0]
type Segment = { to: Point; c1?: Point; c2?: Point }

// d3's monotoneX tangents, so a drawn line and its area follow the same curve and never overshoot the data.
function slope3([x0, y0]: Point, [x1, y1]: Point, [x2, y2]: Point) {
  const h0 = x1 - x0
  const h1 = x2 - x1
  const s0 = (y1 - y0) / (h0 || (h1 < 0 ? -0 : 0))
  const s1 = (y2 - y1) / (h1 || (h0 < 0 ? -0 : 0))
  const p = (s0 * h1 + s1 * h0) / (h0 + h1)
  const sign = (v: number) => (v < 0 ? -1 : 1)
  return (
    (sign(s0) + sign(s1)) *
      Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0
  )
}
function slope2([x0, y0]: Point, [x1, y1]: Point, t: number) {
  const h = x1 - x0
  return h ? ((3 * (y1 - y0)) / h - t) / 2 : t
}

function segments(points: Point[], interpolation: "monotone" | "linear") {
  const n = points.length
  if (interpolation === "linear" || n < 3)
    return points.slice(1).map((to): Segment => ({ to }))
  const t: number[] = new Array(n).fill(0)
  for (let i = 1; i < n - 1; i++)
    t[i] = slope3(points[i - 1]!, points[i]!, points[i + 1]!)
  t[0] = slope2(points[0]!, points[1]!, t[1]!)
  t[n - 1] = slope2(points[n - 2]!, points[n - 1]!, t[n - 2]!)
  return points.slice(1).map((to, i): Segment => {
    const [x0, y0] = points[i]!
    const [x1, y1] = to
    const dx = (x1 - x0) / 3
    return {
      c1: [x0 + dx, y0 + dx * t[i]!],
      c2: [x1 - dx, y1 - dx * t[i + 1]!],
      to,
    }
  })
}

function trace(
  ctx: CurveContext,
  start: Point,
  segs: Segment[],
  join: boolean,
) {
  if (join) ctx.lineTo(...start)
  else ctx.moveTo(...start)
  for (const { c1, c2, to } of segs) {
    if (c1 && c2) ctx.bezierCurveTo(...c1, ...c2, ...to)
    else ctx.lineTo(...to)
  }
}

function draw(ctx: CurveContext, start: Point, segs: Segment[], seed: number) {
  if (!segs.length) {
    ctx.moveTo(...start)
    ctx.closePath()
    return
  }
  const p = ([x, y]: Point) => `${q(x)} ${q(y)}`
  const d =
    `M${p(start)}` +
    segs
      .map(({ c1, c2, to }) =>
        c1 && c2 ? `C${p(c1)} ${p(c2)} ${p(to)}` : `L${p(to)}`,
      )
      .join("")
  for (const { op, data } of roughOps(d, seed)) {
    const [a = 0, b = 0, c = 0, e = 0, f = 0, g = 0] = data.map(tenth)
    if (op === "move") ctx.moveTo(a, b)
    else if (op === "lineTo") ctx.lineTo(a, b)
    else ctx.bezierCurveTo(a, b, c, e, f, g)
  }
}

/**
 * A curve for `<Line type>` and `<Area type>` whose stroke looks drawn: two pen passes through the exact data
 * points. An area's fill keeps the plain curve, so fill and stroke meet. Horizontal layouts.
 */
export function drawnCurve(
  interpolation: "monotone" | "linear" = "monotone",
  seed: string | number = "chart",
): CurveFactory {
  const s = seedOf(seed) || 1
  return (context: CurveContext) => {
    let inArea = false
    let closing = false
    let points: Point[] = []
    return {
      areaStart() {
        inArea = true
        closing = false
      },
      areaEnd() {
        inArea = false
      },
      lineStart() {
        points = []
      },
      point(x: number, y: number) {
        const last = points[points.length - 1]
        if (!last || last[0] !== +x || last[1] !== +y) points.push([+x, +y])
      },
      lineEnd() {
        const [start] = points
        if (start && inArea) {
          trace(context, start, segments(points, interpolation), closing)
          if (closing) context.closePath()
        } else if (start) {
          draw(context, start, segments(points, interpolation), s)
        }
        if (inArea) closing = !closing
      },
    }
  }
}

// ---- Bars and slices ----------------------------------------------------------------------------------------------

function DrawnBar({
  x = 0,
  y = 0,
  width = 0,
  height = 0,
  fill,
  stroke,
  dataKey,
  index,
  value,
}: BarShapeProps & { dataKey?: unknown }) {
  const x0 = Math.min(x, x + width)
  const y0 = Math.min(y, y + height)
  const w = Math.abs(width)
  const h = Math.abs(height)
  const seed = seedOf(`${String(dataKey)}:${index}:${String(value)}`)
  const d = React.useMemo(() => {
    if (w < 1 || h < 1) return null
    const [l, t, r, b] = [q(x0), q(y0), q(x0 + w), q(y0 + h)]
    return opsToPath(
      roughOps(`M${l} ${t}L${r} ${t}L${r} ${b}L${l} ${b}Z`, seed),
    )
  }, [x0, y0, w, h, seed])
  return (
    <g className="patina-chart-bar">
      <rect x={x0} y={y0} width={w} height={h} fill={fill} />
      {d && (
        <path
          d={d}
          fill="none"
          stroke={inkOf(fill, stroke, dataKey)}
          strokeWidth={1.5}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
    </g>
  )
}

/** A bar for `<Bar shape>`: the exact rectangle in its fill, outlined by a drawn pen line. */
export function drawnBar(props: BarShapeProps) {
  return <DrawnBar {...props} />
}

const RADIAN = Math.PI / 180
function polar(cx: number, cy: number, r: number, angle: number): string {
  return `${q(cx + Math.cos(-RADIAN * angle) * r)} ${q(cy + Math.sin(-RADIAN * angle) * r)}`
}

function DrawnSector(props: PieSectorShapeProps) {
  const { cx = 0, cy = 0, innerRadius = 0, outerRadius = 0 } = props
  const { startAngle = 0, endAngle = 0, fill, stroke, name, value } = props
  const seed = seedOf(`${String(name)}:${String(value)}`)
  const d = React.useMemo(() => {
    const delta =
      Math.sign(endAngle - startAngle) *
      Math.min(Math.abs(endAngle - startAngle), 359.999)
    const end = startAngle + delta
    if (Math.abs(delta) < 0.5 || outerRadius < 1) return null
    const large = Math.abs(delta) > 180 ? 1 : 0
    const ro = q(outerRadius)
    let path = `M${polar(cx, cy, ro, startAngle)}A${ro} ${ro} 0 ${large} ${+(startAngle > end)} ${polar(cx, cy, ro, end)}`
    if (innerRadius > 0) {
      const ri = q(innerRadius)
      path += `L${polar(cx, cy, ri, end)}A${ri} ${ri} 0 ${large} ${+(startAngle <= end)} ${polar(cx, cy, ri, startAngle)}Z`
    } else path += `L${q(cx)} ${q(cy)}Z`
    return opsToPath(roughOps(path, seed))
  }, [cx, cy, innerRadius, outerRadius, startAngle, endAngle, seed])
  return (
    <g className="patina-chart-sector">
      <Sector {...props} stroke="none" />
      {d && (
        <path
          d={d}
          fill="none"
          stroke={inkOf(fill, stroke, undefined)}
          strokeWidth={props.isActive ? 2.25 : 1.5}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
    </g>
  )
}

/** A slice for `<Pie shape>`: the exact sector in its fill, outlined by a drawn pen line, heavier when active. */
export function drawnSector(props: PieSectorShapeProps) {
  return <DrawnSector {...props} />
}

"use client"

import * as React from "react"
import { seedOf, stream } from "@/patina/ink/seed"
import { cn } from "@/patina/lib/utils"
import {
  hatchId,
  seriesStyle,
  useChart,
  type ChartConfig,
  type ChartHatch,
} from "@/patina/ui/chart-context"

// Hatch fills: one SVG pattern per series, defined once per chart and printed in the series' ink over a faint tint
// of it, the way a riso screen prints. Each kind reads differently without colour; the angle leans a few degrees by
// a seed from the series key, so it is the same on the server, in the browser and in every build.

const TINT = 0.16

function HatchPattern({
  id,
  hatch,
  color,
  seed,
}: {
  id: string
  hatch: ChartHatch
  color: string
  seed: string
}) {
  const lean = Math.round(stream(seedOf(seed), "hatch").signed() * 8)
  const tile = (size: number, angle: number, marks: React.ReactNode) => (
    <pattern
      id={id}
      width={size}
      height={size}
      patternUnits="userSpaceOnUse"
      patternTransform={`rotate(${angle})`}
    >
      <rect width={size} height={size} fill={color} fillOpacity={TINT} />
      <g fill={color}>{marks}</g>
    </pattern>
  )

  switch (hatch) {
    case "cross":
      return tile(
        7,
        45 + lean,
        <>
          <rect width={1.25} height={7} />
          <rect width={7} height={1.25} />
        </>,
      )
    case "dots":
      return tile(
        6,
        lean,
        <>
          <circle cx={1.5} cy={1.5} r={1.3} />
          <circle cx={4.5} cy={4.5} r={1.3} />
        </>,
      )
    case "horizontal":
      return tile(5, lean, <rect width={5} height={1.4} />)
    case "antidiagonal":
      return tile(4.5, -45 + lean, <rect width={1.25} height={4.5} />)
    default:
      return tile(6, 45 + lean, <rect width={1.5} height={6} />)
  }
}

/** Every series' hatch for one chart, in a hidden SVG that the chart's shapes refer to by id. */
export function ChartHatchDefs({
  chartId,
  config,
}: {
  chartId: string
  config: ChartConfig
}) {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      width="0"
      height="0"
      className="pointer-events-none absolute"
    >
      <defs>
        {Object.keys(config).map((key) => (
          <HatchPattern
            key={key}
            id={hatchId(chartId, key)}
            hatch={seriesStyle(config, key).hatch}
            color={`var(--color-${key})`}
            seed={key}
          />
        ))}
      </defs>
    </svg>
  )
}

/**
 * A series' key in a tooltip or legend: a small square of its hatch with an ink edge, a short stroke in its dash
 * pattern for a line, or a plain ink square when the series has no hatch.
 */
export function ChartSwatch({
  seriesKey,
  color,
  variant = "hatch",
  dash,
  className,
}: {
  seriesKey?: string
  color?: string
  variant?: "hatch" | "ink" | "line"
  dash?: string | number
  className?: string
}) {
  const { chartId } = useChart()
  const ink =
    color ?? (seriesKey ? `var(--color-${seriesKey})` : "currentColor")

  if (variant === "line") {
    return (
      <svg
        data-slot="chart-swatch"
        aria-hidden="true"
        viewBox="0 0 16 10"
        className={cn("h-2.5 w-4 shrink-0 overflow-visible", className)}
      >
        <line
          x1={1}
          y1={5}
          x2={15}
          y2={5}
          stroke={ink}
          strokeWidth={2}
          strokeLinecap="round"
          strokeDasharray={dash}
        />
      </svg>
    )
  }

  if (variant === "hatch" && seriesKey) {
    return (
      <svg
        data-slot="chart-swatch"
        aria-hidden="true"
        viewBox="0 0 12 12"
        className={cn("size-3 shrink-0", className)}
      >
        <rect
          x={0.75}
          y={0.75}
          width={10.5}
          height={10.5}
          rx={1}
          fill={`url(#${hatchId(chartId, seriesKey)})`}
          stroke={ink}
          strokeWidth={1.5}
        />
      </svg>
    )
  }

  return (
    <span
      data-slot="chart-swatch"
      aria-hidden="true"
      className={cn("size-2.5 shrink-0 rounded-[1px]", className)}
      style={{ backgroundColor: ink }}
    />
  )
}

"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"
import type { TooltipValueType } from "recharts"
import { cn } from "@/patina/lib/utils"
import {
  getPayloadConfigKey,
  isHatchFill,
  useChart,
} from "@/patina/ui/chart-context"
import { ChartSwatch } from "@/patina/ui/chart-hatch"

// The tooltip is a small float sheet of card stock, like a popover: the label in the mono voice, one row per series
// with its swatch, name and a tabular mono value. The legend is a row of mono labels, each with the series' hatch
// (or its stroke and dash, for a line). Both use text inks; the print inks stay in the swatches.

type TooltipNameType = number | string

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean
    hideIndicator?: boolean
    indicator?: "line" | "dot" | "dashed"
    nameKey?: string
    labelKey?: string
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart()

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null
    }

    const [item] = payload
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`
    const configKey = getPayloadConfigKey(config, item, key)
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : configKey && config[configKey]?.label

    const classes = cn("label-mono font-semibold text-ink", labelClassName)
    if (labelFormatter) {
      return <div className={classes}>{labelFormatter(value, payload)}</div>
    }

    if (!value) {
      return null
    }

    return <div className={classes}>{value}</div>
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ])

  if (!active || !payload?.length) {
    return null
  }

  const nestLabel = payload.length === 1 && indicator !== "dot"

  return (
    <div
      data-slot="chart-tooltip"
      className={cn(
        "float-sheet grid min-w-36 items-start gap-hair px-tight py-hair",
        className,
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`
            const configKey = getPayloadConfigKey(config, item, key)
            const itemConfig = configKey ? config[configKey] : undefined
            const fill = (item.payload as { fill?: unknown } | undefined)?.fill
            const hatched = isHatchFill(item.fill) || isHatchFill(fill)
            const raw = color ?? (hatched ? undefined : (item.color ?? fill))
            const ink =
              (typeof raw === "string" && !isHatchFill(raw) && raw) ||
              (configKey ? `var(--color-${configKey})` : "var(--ink)")

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg:not([data-slot=chart-swatch])]:size-3 [&>svg:not([data-slot=chart-swatch])]:text-ink-2",
                  indicator === "dot" && "items-center",
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator &&
                      (indicator === "dot" ? (
                        <ChartSwatch
                          seriesKey={configKey}
                          color={ink}
                          variant={hatched ? "hatch" : "ink"}
                        />
                      ) : (
                        <div
                          className={cn(
                            "shrink-0 rounded-[1px] border-(--swatch) bg-(--swatch)",
                            indicator === "line" && "w-1",
                            indicator === "dashed" &&
                              "w-0 border-[1.5px] border-dashed bg-transparent",
                            nestLabel && indicator === "dashed" && "my-0.5",
                          )}
                          style={{ "--swatch": ink } as React.CSSProperties}
                        />
                      ))
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between gap-snug",
                        nestLabel ? "items-end" : "items-center",
                      )}
                    >
                      <div className="grid gap-1">
                        {nestLabel ? tooltipLabel : null}
                        <span className="label-mono text-ink-2">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-label text-small leading-none font-semibold text-ink tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
      </div>
    </div>
  )
}

function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: React.ComponentProps<"div"> & {
  hideIcon?: boolean
  nameKey?: string
} & RechartsPrimitive.DefaultLegendContentProps) {
  const { config } = useChart()

  if (!payload?.length) {
    return null
  }

  const keys = Object.keys(config)
  const order = (key?: string) => {
    const at = key ? keys.indexOf(key) : -1
    return at < 0 ? keys.length : at
  }

  return (
    <div
      data-slot="chart-legend"
      className={cn(
        "flex flex-wrap items-center justify-center gap-x-snug gap-y-hair",
        verticalAlign === "top" ? "pb-tight" : "pt-tight",
        className,
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`
          return { item, configKey: getPayloadConfigKey(config, item, key) }
        })
        // In config order, the order inks and hatches are dealt in, not Recharts' alphabetical one.
        .sort((a, b) => order(a.configKey) - order(b.configKey))
        .map(({ item, configKey }, index) => {
          const itemConfig = configKey ? config[configKey] : undefined
          const series = item.payload as
            { fill?: unknown; strokeDasharray?: string | number } | undefined
          const hatched = isHatchFill(series?.fill) || isHatchFill(item.color)
          const variant = hatched
            ? "hatch"
            : item.type === "line"
              ? "line"
              : "ink"
          const ink =
            !isHatchFill(item.color) && item.color
              ? item.color
              : configKey && `var(--color-${configKey})`

          return (
            <div
              key={index}
              className="label-mono flex items-center gap-1.5 text-ink-2 [&>svg:not([data-slot=chart-swatch])]:size-3 [&>svg:not([data-slot=chart-swatch])]:text-ink-2"
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <ChartSwatch
                  seriesKey={configKey}
                  color={ink || undefined}
                  variant={variant}
                  dash={series?.strokeDasharray}
                />
              )}
              {itemConfig?.label ?? item.value}
            </div>
          )
        })}
    </div>
  )
}

